/// Install only an invalidation witness. This changes no semantic field
/// and does not keep the index or any other object alive. A second visit
/// with the same certificate must not drop (and invalidate) that witness.
pub(crate) fn boxhead_anchor_index_witness(self, gc: &Mutation<'gc>, token: &Rc<Validity>) {
    let mut write = self.0.borrow_mut(gc);
    if !write.anchor_index_witness.as_ref().is_some_and(|witness| witness.matches(token)) {
        write.anchor_index_witness = Some(Witness::new(token));
    }
}

/// Bounded raw inspection for optional index preparation. It neither
/// admits metadata nor reads a getter/prototype/native property. A miss
/// disables the optional index; the checkpoint's fresh reader is intact.
pub(crate) fn boxhead_anchor_index_edges_into(self, limit: usize,
    edges: &mut Vec<(AvmString<'gc>, Value<'gc>)>) -> Option<usize> {
    edges.clear();
    let read = self.0.borrow();
    if !matches!(read.native, NativeObject::None | NativeObject::Array(_))
        || read.watchers.iter().next().is_some() || read.interfaces.is_some() { return None; }
    if let Some(cached) = &read.anchor_metadata {
        if cached.raw_count > limit { return None; }
        edges.extend_from_slice(&cached.edges);
        return Some(cached.raw_count);
    }
    let mut count = 0;
    for (key, property) in read.properties.iter() {
        if count == limit || property.getter().is_some() || property.setter().is_some() {
            edges.clear();
            return None;
        }
        count += 1;
        let value = property.data();
        if !key.eq_with_case(b"__proto__", true)
            && matches!(value, Value::Object(_) | Value::MovieClip(_)) { edges.push((key, value)); }
    }
    Some(count)
}

